actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec

def fromD = fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
def thruD = thruDate ?: fromD
def dStart = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def dEnd = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')

def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def wf = ec.entity.find("zenith.erp.pos.PosStockWastage")
    .condition("wastageDate", "greater-equals", dStart)
    .condition("wastageDate", "less-equals", dEnd)
if (_org) wf.condition("organizationPartyId", _org)
def wastages = wf.list()

def reasonMap = new LinkedHashMap(); def productMap = new LinkedHashMap()
wastages.each { w ->
    def reason = w.wastageReason ?: 'Other'
    if (!reasonMap[reason]) {
        def ev = ec.entity.find("moqui.basic.Enumeration").condition("enumId", reason).one()
        reasonMap[reason] = [name: ev?.description ?: reason, loss: 0.0G, qty: 0.0G, n: 0]
    }
    reasonMap[reason].loss += (w.totalLoss ?: 0) as BigDecimal
    reasonMap[reason].qty += (w.quantity ?: 0) as BigDecimal
    reasonMap[reason].n++
    def pn = w.productName ?: w.productId ?: 'Unknown'
    if (!productMap[pn]) productMap[pn] = [name: pn, loss: 0.0G, qty: 0.0G, n: 0]
    productMap[pn].loss += (w.totalLoss ?: 0) as BigDecimal
    productMap[pn].qty += (w.quantity ?: 0) as BigDecimal
    productMap[pn].n++
}
def reasons = reasonMap.values().sort { -(it.loss as BigDecimal) }
def products = productMap.values().sort { -(it.loss as BigDecimal) }
def tLoss = reasons.sum { it.loss } ?: 0.0G
def tQty = reasons.sum { it.qty } ?: 0.0G
def tN = reasons.sum { it.n } ?: 0

def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def amt = { v -> String.format("%.2f", (v ?: 0.0) as double) }

StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Wastage Summary\n")
csv.append("Period: ${fromD} to ${thruD}\n")
csv.append("Generated on: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Total Loss Amount,${amt(tLoss)}\n")
csv.append("Total Quantity Wasted,${amt(tQty)}\n\n")

csv.append("By Reason\n")
csv.append("Reason,Entries,Qty Wasted,Loss Amount\n")
reasons.each { csv.append("${esc(it.name)},${it.n},${amt(it.qty)},${amt(it.loss)}\n") }
csv.append("Total,${tN},${amt(tQty)},${amt(tLoss)}\n\n")

csv.append("By Product\n")
csv.append("Product,Entries,Qty Wasted,Loss Amount\n")
products.each { csv.append("${esc(it.name)},${it.n},${amt(it.qty)},${amt(it.loss)}\n") }
csv.append("Total,${tN},${amt(tQty)},${amt(tLoss)}\n")

String fileName = "Wastage_Summary_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv"
ec.web.sendTextResponse(csv.toString(), "text/csv", fileName)

def zinr = context.zinr ?: com.zenith.Fmt.INSTANCE
// ZE-SALES-014 f/u: org-isolate (standalone render skips the authz filter)
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def _wastageFind = ec.entity.find("zenith.erp.pos.PosStockWastage")
    .condition("wastageDate", "greater-equals", dayStart)
    .condition("wastageDate", "less-equals", dayEnd)
if (_org) _wastageFind.condition("organizationPartyId", _org)
def wastages = _wastageFind.list()

grandTotalLoss = BigDecimal.ZERO
grandTotalQty = BigDecimal.ZERO
reasonSummary = []
productSummary = []

if (wastages) {
    def reasonMap = new LinkedHashMap()
    def productMap = new LinkedHashMap()
    wastages.each { w ->
        def reason = w.wastageReason ?: 'Other'
        if (!reasonMap[reason]) {
            def enumVal = ec.entity.find("moqui.basic.Enumeration").condition("enumId", reason).one()
            reasonMap[reason] = [reason: reason, reasonName: enumVal?.description ?: reason,
                totalLoss: BigDecimal.ZERO, totalQty: BigDecimal.ZERO, entryCount: 0 as int]
        }
        reasonMap[reason].totalLoss += (w.totalLoss ?: 0) as BigDecimal
        reasonMap[reason].totalQty += (w.quantity ?: 0) as BigDecimal
        reasonMap[reason].entryCount++
        def pName = w.productName ?: w.productId ?: 'Unknown'
        if (!productMap[pName]) {
            productMap[pName] = [productName: pName,
                totalLoss: BigDecimal.ZERO, totalQty: BigDecimal.ZERO, entryCount: 0 as int]
        }
        productMap[pName].totalLoss += (w.totalLoss ?: 0) as BigDecimal
        productMap[pName].totalQty += (w.quantity ?: 0) as BigDecimal
        productMap[pName].entryCount++
    }
    reasonSummary = reasonMap.values().sort { -(it.totalLoss as BigDecimal) }
    productSummary = productMap.values().sort { -(it.totalLoss as BigDecimal) }
    grandTotalLoss = reasonSummary.sum { it.totalLoss } ?: BigDecimal.ZERO
    grandTotalQty = reasonSummary.sum { it.totalQty } ?: BigDecimal.ZERO
}

// pre-format for the render-mode tables + cards (Indian grouping via zinr)
def fmtAmt = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def fmtQty = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0')) }
reasonSummary.each { it.qtyStr = fmtQty(it.totalQty); it.lossStr = fmtAmt(it.totalLoss) }
productSummary.each { it.qtyStr = fmtQty(it.totalQty); it.lossStr = fmtAmt(it.totalLoss) }
reasonTotEntries = (reasonSummary.sum { it.entryCount } ?: 0) as int
productTotEntries = (productSummary.sum { it.entryCount } ?: 0) as int
grandLossCardStr = '₹ ' + fmtAmt(grandTotalLoss)
grandLossStr = fmtAmt(grandTotalLoss)
grandQtyStr = fmtQty(grandTotalQty)
reasonTotEntriesStr = fmtQty(reasonTotEntries)
productTotEntriesStr = fmtQty(productTotEntries)
